at::Tensor max_reduce_cuda(const at::Tensor& input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 3, "input must be a 3D tensor");
    TORCH_CHECK(
        input.scalar_type() == at::kFloat ||
        input.scalar_type() == at::kDouble ||
        input.scalar_type() == at::kHalf,
        "only float16, float32, and float64 are supported");

    auto x = input.contiguous();

    if (dim < 0) {
        dim += 3;
    }
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be in [-3, 2]");

    const int64_t d0 = x.size(0);
    const int64_t d1 = x.size(1);
    const int64_t d2 = x.size(2);

    std::vector<int64_t> out_sizes;
    if (dim == 0) {
        out_sizes = {d1, d2};
    } else if (dim == 1) {
        out_sizes = {d0, d2};
    } else {
        out_sizes = {d0, d1};
    }

    auto out = at::empty(out_sizes, x.options());
    const int64_t out_numel = out.numel();

     constexpr int threads = 256;
     constexpr int dim1_float_threads = 128;
     const int64_t dim1_groups = d0 * ((d2 + 3) / 4);
     const int64_t dim1_vec_groups = d0 * ((d2 + 127) / 128);
     const int64_t dim1_float_warps = dim1_float_threads / 32;
     const int64_t launch_items =
         (dim == 1)
             ? ((x.scalar_type() == at::kFloat)
                    ? ((dim1_vec_groups + dim1_float_warps - 1) /
                       dim1_float_warps)
                    : ((dim1_groups + threads - 1) / threads))
             : ((dim == 2)
                    ? out_numel
                    : ((out_numel + threads - 1) / threads));
     const dim3 blocks(static_cast<unsigned int>(launch_items));
    const size_t shared_bytes = (dim == 2) ? ((x.scalar_type() == at::kFloat) ? 8 : threads) * x.element_size() : 0;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        x.scalar_type(),
        "max_reduce_cuda",
        [&] {
             max_reduce_kernel<scalar_t><<<blocks, (dim == 1 && x.scalar_type() == at::kFloat) ? dim1_float_threads : threads, shared_bytes, stream>>>(
                x.data_ptr<scalar_t>(),
                out.data_ptr<scalar_t>(),
                d0,
                d1,
                d2,
                dim);
        });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
